const $ = s => document.querySelector(s);
const esc = v => String(v ?? "").replace(/[&<>\"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const fmt = n => { n=Number(n||0); if(n<1024)return `${n} B`; if(n<1048576)return `${(n/1024).toFixed(1)} KB`; if(n<1073741824)return `${(n/1048576).toFixed(1)} MB`; return `${(n/1073741824).toFixed(1)} GB`; };
const getLang=()=>localStorage.getItem("kc_lang_v4")||"en";
const date = v => v ? new Date(v).toLocaleString(getLang()==="tr"?"tr-TR":"en-US",{dateStyle:"medium",timeStyle:"short"}) : "—";
const S = {user:null,tab:"overview",projects:[],query:"",config:null,selectedFiles:[],profile:null,authMode:"login",authToken:null};
const A="/ui/";

async function api(url,opts={}){
  const r=await fetch(url,{credentials:"same-origin",...opts,headers:{"Content-Type":"application/json",...(opts.headers||{})}});
  const ct=r.headers.get("content-type")||""; const text=await r.text(); let d={};
  try{d=ct.includes("json")?JSON.parse(text):{error:text,body:text,contentType:ct}}catch{d={error:text,body:text,contentType:ct}}
  if(!r.ok){const e=new Error(d.error||d.message||`HTTP ${r.status}`);e.status=r.status;e.code=d.code;e.body=text;e.contentType=ct;e.data=d;throw e}
  return d;
}
function toast(msg,type="success"){const e=$("#toast");if(!e)return;e.textContent=msg;e.className=`toast ${type}`;clearTimeout(window.__toast);window.__toast=setTimeout(()=>e.className="toast hidden",4200)}
function openModal(html){const m=$("#modal");m.classList.remove("hidden");m.innerHTML=html}
function closeModal(){const m=$("#modal");m.classList.add("hidden");m.innerHTML=""}
function nav(id,label,img,fallback){return `<button class="navbtn ${S.tab===id?"active":""}" onclick="S.tab='${id}';closeMenu();renderApp()"><img class="navicon" src="${A}${img}" onerror="this.style.display='none';this.nextElementSibling.style.display='inline-block'"><span class="navFallback" style="display:none">${fallback}</span><span>${label}</span></button>`}

function stat(label,num,sub=""){return `<div class="card stat"><div class="label">${esc(label)}</div><div class="num">${esc(num)}</div>${sub?`<div class="muted small" style="margin-top:5px">${esc(sub)}</div>`:""}</div>`}
function statusPill(status){const c=status==="live"?"":status==="suspended"?"red":"warn";return `<span class="pill ${c}">${esc(status||"unknown").toUpperCase()}</span>`}
function projectCard(p,admin=false){return `<div class="card project"><div class="projecthead"><div class="projectname">${esc(p.name)}</div>${statusPill(p.status)}</div><div class="url">${esc(p.slug)}.${esc(S.config?.domain||"example.com")}</div>${admin?`<div class="muted small">Owner: ${esc(p.ownerEmail||"—")}</div>`:""}<div class="projectmeta" style="margin-top:9px"><span>◫ ${p.files||0} file</span><span>◌ ${fmt(p.bytes)}</span><span>◉ ${p.views||0} views</span></div><div class="projectactions"><button class="btn" onclick="window.open('${esc(p.url)}','_blank')">Open ↗</button><button class="btn" onclick="projectDetails('${p.id}')">Details</button><button class="btn" onclick="quickRedeploy('${p.id}')">New release</button>${admin?`<button class="btn danger" onclick="adminDeleteProject('${p.id}')">Delete</button>`:`<button class="btn danger" onclick="deleteProject('${p.id}')">Delete</button>`}</div></div>`}


function ecosystemCard(icon,title,eyebrow,copy,url,accent,details){
  return `<a class="ecoCard eco-${accent}" href="${url}" target="_blank" rel="noopener noreferrer">
    <div class="ecoGlow"></div>
    <div class="ecoTop"><span class="ecoIcon">${icon}</span><span class="ecoArrow">↗</span></div>
    <div class="ecoEyebrow">${eyebrow}</div>
    <h3>${title}</h3>
    <p>${copy}</p>
    <div class="ecoDetails">${details.map(x=>`<span>${x}</span>`).join("")}</div>
    <div class="ecoCta">Open ${title} <b>→</b></div>
  </a>`;
}
