function selectLandingFlow(index){
  const data=[
    ['STEP 01 / INPUT','Bring your project.','Drop a ZIP, choose a folder or select the files that make up your site. Deploy Website keeps the path structure intact.','Prepare a clean release →'],
    ['STEP 02 / PROCESS','Prepare the release.','Your files become a clean, isolated snapshot with a clear release boundary before anything is made live.','Publish the release →'],
    ['STEP 03 / OUTPUT','Put it live.','The release gets its live URL. Open it, share it and keep the exact version visible in your workspace.','Keep shipping →'],
    ['STEP 04 / CONTROL','Keep shipping.','Publish another version, inspect the trail or restore a previous snapshot when you need a safe way back.','You stay in control ✓']
  ];
  const x=data[index]||data[0], p=document.querySelector('#landingFlowPreview'); if(!p)return;
  p.querySelector('.flowPreviewTop b').textContent=x[0];p.querySelector('h3').textContent=x[1];p.querySelector('p').textContent=x[2];p.querySelector('.flowHint span').textContent=x[3];
  document.querySelectorAll('.flowItem').forEach((e,i)=>e.classList.toggle('active',i===index));
  p.classList.remove('flowFlash');void p.offsetWidth;p.classList.add('flowFlash');
}

function setRouteState(kind, mode=""){
  try{history.pushState({kc:kind,mode},"",location.pathname+location.search+location.hash)}catch{}
}
function replaceRouteState(kind, mode=""){
  try{history.replaceState({kc:kind,mode},"",location.pathname+location.search+location.hash)}catch{}
}
function goLanding(){
  try{history.pushState({kc:"landing"},"","/")}catch{}
  renderLanding();
}
window.addEventListener("popstate",()=>{
  const st=history.state||{};
  if(st.kc==="landing"){renderLanding();return}
  if(st.kc==="auth"){renderAuth(st.mode||"login",true);return}
  if(st.kc==="app"){renderApp(true);return}
  renderLanding();
});

function renderLanding(){
  document.title="Deploy Website — Private Deployment Cloud";
  if(!history.state?.kc) replaceRouteState("landing");
  document.body.innerHTML=`<div id="root">${landingView()}</div><div id="modal" class="modal hidden"></div><div id="toast" class="toast hidden"></div>`;
}

async function boot(){
  const path=location.pathname, qs=new URLSearchParams(location.search);
  if(path==="/verify-email" && qs.get("token")){ try{S.config=await api("/api/config")}catch{} return verifyEmail(qs.get("token")); }
  if(path==="/reset-password" && qs.get("token")){ try{S.config=await api("/api/config")}catch{} S.authToken=qs.get("token"); return renderAuth("reset"); }
  // Establish a landing state underneath auth so mobile/browser Back returns to the site instead of exiting.
  if(path==="/login" || path==="/register"){
    try{history.replaceState({kc:"landing"},"","/");history.pushState({kc:"auth",mode:path.slice(1)},"",path)}catch{}
    renderAuth(path==="/register"?"register":"login",true);
  }else{
    try{history.replaceState({kc:"landing"},"",location.pathname+location.search+location.hash)}catch{}
    renderLanding();
  }
  try{S.config=await api("/api/config")}catch{S.config={domain:"example.com",dashboardHost:"app.example.com",brand:"deploy-website",registration:true}}
  try{const d=await api("/api/auth/me");S.user=d.user;if(S.user && path!=="/login" && path!=="/register") renderApp();}catch{}
}

