function authShell(mode){
  const isReg=mode==="register", isForgot=mode==="forgot", isReset=mode==="reset", isVerify=mode==="verify";
  const title=isReg?"Create your account.":isForgot?"Reset your password.":isReset?"Set a new password.":isVerify?"Email verified.":"Welcome back.";
  const desc=isReg?"Create your account, verify your email, and start publishing.":isForgot?"Enter your email and we will send a secure reset link.":isReset?"Set a new password and return to your workspace.":isVerify?"Your account is verified. You can now enter the workspace.":"Sign in to publish, manage and control your releases.";
  const tabs=!isForgot&&!isReset&&!isVerify?`<div class="authTabs"><button class="authTab ${!isReg?"active":""}" onclick="renderAuth('login')">Sign in</button><button class="authTab ${isReg?"active":""}" onclick="renderAuth('register')">Sign up</button></div>`:"";
  return `<div class="authPage"><div class="authPageInner"><section class="authShowcase"><div class="showcaseKicker">DEPLOY WEBSITE · PRIVATE DEPLOYMENT</div><h1 class="showcaseTitle">Publish. <em>Manage.</em><br>In control.</h1><p class="showcaseCopy">Upload websites and projects, publish them to a secure subdomain, and manage every release from one focused workspace.</p><div class="showcaseCards"><div class="showcaseCard"><span class="showcaseIndex">01</span><div><b>Fast publishing</b><span>ZIP, folder or files → live URL.</span></div><i>↑</i></div><div class="showcaseCard"><span class="showcaseIndex">02</span><div><b>Snapshot releases</b><span>Every deploy gets a clear version.</span></div><i>◈</i></div><div class="showcaseCard"><span class="showcaseIndex">03</span><div><b>Safe rollback</b><span>Return to a known-good snapshot.</span></div><i>↶</i></div><div class="showcaseCard"><span class="showcaseIndex">04</span><div><b>Clean live URLs</b><span>Open, share and verify with ease.</span></div><i>↗</i></div></div><div class="showcaseMetric"><i class="metricDot"></i><span>Responsive workspace</span><span>•</span><span>Snapshot-first</span><span>•</span><span>Cache controlled</span></div></section><section><div class="authbox"><div class="authHeader"><img class="authLogo" src="/branding/logo.png?v=4.1.0" onerror="this.src='/branding/logo.svg?v=4.1.0'"><div class="authBrandText"><b>deploy-website</b><span>PRIVATE DEPLOYMENT CLOUD</span></div></div><div class="authIntro"><div class="authEyebrow">${isReg?"NEW ACCOUNT":isForgot||isReset?"ACCOUNT RECOVERY":isVerify?"VERIFICATION":"WORKSPACE"}</div><h1>${title}</h1><p>${desc}</p></div>${tabs}<div class="authFormWrap">${isReg?registerForm():isForgot?forgotForm():isReset?resetForm():isVerify?verifyForm():loginForm()}</div>${!isReset&&!isVerify?authFaq():""}<div class="authBottom"><span>Secure workspace</span><span>•</span><span>Snapshot releases</span><span>•</span><span>Responsive dashboard</span></div></div></section></div>${authFooter()}</div>`;
}
