function resetForm(){return `<div class="field"><div class="fieldLabelRow"><label>New password</label><span class="fieldHint">At least 10 characters</span></div><div class="passwordRow"><input id="password" type="password" autocomplete="new-password"></div></div><div class="field"><label>Confirm new password</label><input id="password2" type="password" autocomplete="new-password"></div><button id="authBtn" class="btn primary authSubmit" onclick="resetPassword()">Update password <span>→</span></button><div id="authError" class="authError hidden"></div>`}
function verifyForm(){return `<div class="verifyPanel"><div class="verifyIcon">✓</div><b>Your email is verified</b><span>Your account is ready. Continue by signing in.</span></div><button class="btn primary authSubmit" onclick="renderAuth('login')">Continue to sign in →</button>`}
function renderAuth(mode,fromHistory=false){if(!fromHistory){setRouteState("auth",mode)}S.authMode=mode;document.body.innerHTML=`<div id="root">${authShell(mode)}</div><div id="modal" class="modal hidden"></div><div id="toast" class="toast hidden"></div>`;updateAuthButton();setTimeout(()=>document.querySelector('#'+(mode==='register'?'username':'email'))?.focus(),40)}
function updateAuthButton(){
  const b=$("#authBtn");
  if(!b || b.disabled) return;
  if(S.authMode==="register") b.innerHTML="Create account <span>→</span>";
  else if(S.authMode==="forgot") b.innerHTML="Send reset link <span>→</span>";
  else if(S.authMode==="reset") b.innerHTML="Update password <span>→</span>";
  else b.innerHTML="Sign in <span>→</span>";
}
function togglePassword(){const i=$("#password");if(!i)return;i.type=i.type==="password"?"text":"password";const btn=document.querySelector('.linkBtn');if(btn&&S.authMode==='login')btn.textContent=i.type==='password'?'Show':'Hide'}
function showAuthError(msg,success=false){const e=$("#authError");if(!e)return;e.textContent=msg;e.className=`authError ${success?"successBox":""}`}
function openTerms(){openModal(`<div class="modalbox termsModal"><div class="modalhead"><div><div class="kicker">deploy-website</div><h2 style="margin:6px 0">Terms of Service</h2><p class="muted small">The basic rules for using the private deployment cloud.</p></div><button class="x" onclick="closeModal()">×</button></div><div class="termsBody"><h3>1. Service use</h3><p>Only publish projects you own or have permission to use.</p><h3>2. Account security</h3><p>Keep your credentials private and secure. You are responsible for activity under your account.</p><h3>3. Content and safety</h3><p>Do not publish malware, phishing, unauthorized content or material intended to abuse the service.</p><h3>4. Email verification</h3><p>New accounts require email verification. Verification and password reset links are single-use and expire.</p><h3>5. Service limits</h3><p>Project, file and storage limits may apply to protect performance and availability.</p><h3>6. Updates</h3><p>These terms may be updated when the service changes. Material changes may be announced separately.</p></div><div class="actions" style="margin-top:18px"><button class="btn primary" onclick="closeModal();if($('#terms'))$('#terms').checked=true">I agree</button></div></div>`)}
async function login(){
  const email=String($("#email")?.value||"").trim().toLowerCase(),password=String($("#password")?.value||"");
  if(!email||!password){showAuthError("Email and password are required.");return}
  const btn=$("#authBtn");btn.disabled=true;btn.innerHTML="Signing in…";
  try{const d=await api("/api/auth/login",{method:"POST",body:JSON.stringify({email,password,website:$("#website")?.value||"",})});S.user=d.user;try{history.replaceState({kc:"app"},"","/")}catch{};renderApp(true)}
  catch(e){if(e.code==="BANNED"){showAuthError(`This account is restricted. ${e.data?.message||"Access was restricted by an administrator."}`)}else if(e.code==="EMAIL_NOT_VERIFIED"){showAuthError("Verify your email first. To resend the verification link, use the button below.");const x=document.createElement('button');x.className='authResend';x.textContent='Resend verification email';x.onclick=()=>resendVerification(email);$("#authError")?.after(x)}else if(e.status===401){showAuthError("Incorrect email or password. Check your credentials.")}else if(e.status===429){showAuthError("Too many attempts. Please wait a few minutes.")}else{showAuthError(e.message||"Could not sign in.")};toast(e.message||"Sign in failed","error")}
  finally{btn.disabled=false;updateAuthButton()}
}
async function registerAccount(){
  const username=String($("#username")?.value||"").trim(),email=String($("#email")?.value||"").trim().toLowerCase(),password=String($("#password")?.value||"");
  if(!username||!email||password.length<10){showAuthError("Username, email and a password of at least 10 characters are required.");return}if(!$("#terms")?.checked){showAuthError("You must accept the Terms to sign up.");$("#terms")?.closest(".termsRow")?.classList.add("termsError");return}
  if(username.length<2){showAuthError("Username must be at least 2 characters.");return}
  const btn=$("#authBtn");btn.disabled=true;btn.innerHTML="Creating account…";
  try{const d=await api("/api/auth/register",{method:"POST",body:JSON.stringify({username,email,password,termsAccepted:true,website:$("#website")?.value||"",})});renderAuth("login");showAuthError("Account created. Open the verification link sent to your email, then sign in.",true);toast("Verification email sent 🎉")}
  catch(e){showAuthError(e.message||"Sign up failed");toast(e.message||"Sign up failed","error")}
  finally{btn.disabled=false;updateAuthButton()}
}
async function resendVerification(email){try{await api("/api/auth/resend-verification",{method:"POST",body:JSON.stringify({email})});toast("Verification email sent again 🎉")}catch(e){toast(e.message||"Email could not be sent","error")}}
async function forgotPassword(){const email=String($("#email")?.value||"").trim().toLowerCase();if(!email){showAuthError("Enter your email address.");return}const btn=$("#authBtn");btn.disabled=true;btn.innerHTML="Sending…";try{const d=await api("/api/auth/forgot-password",{method:"POST",body:JSON.stringify({email})});showAuthError(d.message||"If an account exists, a reset link was sent.",true);toast("Email sent")}catch(e){showAuthError(e.message||"Operation failed");toast(e.message||"Operation failed","error")}finally{btn.disabled=false;updateAuthButton()}}
async function resetPassword(){const password=String($("#password")?.value||""),password2=String($("#password2")?.value||"");if(password.length<10){showAuthError("Password must be at least 10 characters.");return}if(password!==password2){showAuthError("Passwords do not match.");return}const btn=$("#authBtn");btn.disabled=true;btn.innerHTML="Updating…";try{await api("/api/auth/reset-password",{method:"POST",body:JSON.stringify({token:S.authToken,password})});renderAuth("login");showAuthError("Password updated. You can now sign in.",true);toast("Password updated 🎉")}catch(e){showAuthError(e.message||"The link is invalid or expired.");toast(e.message||"Could not update password","error")}finally{btn.disabled=false;updateAuthButton()}}
async function verifyEmail(token){document.body.innerHTML=`<div id="root">${authShell("verify")}</div><div id="toast" class="toast hidden"></div>`;try{await api(`/api/auth/verify-email?token=${encodeURIComponent(token)}`);renderAuth("verify");toast("Email verified 🎉")}catch(e){renderAuth("login");showAuthError(e.message||"Verification link is invalid or expired.")}}

function renderApp(fromHistory=false){
  if(!fromHistory && !history.state?.kc) replaceRouteState("app");
 document.body.innerHTML=`<div id="root"><div class="mobileoverlay" id="mobileOverlay" onclick="closeMenu()"></div><div class="app"><aside class="sidebar" id="side"><div class="brand"><img class="brandLogo" src="/branding/logo.png?v=4.1.0" onerror="this.src='/branding/logo.svg?v=4.1.0'"><div class="brandText"><b>deploy-website</b><span>PRIVATE DEPLOYMENT CLOUD</span></div></div><div class="navLabel">WORKSPACE</div><div class="nav">${nav("overview","Overview","overview.png","⌂")}${nav("projects","Projects","projects.png","◈")}${nav("deploy","Deploy","deploy.png","↑")}</div><div class="navLabel">ACCOUNT</div><div class="nav">${nav("account","Account","../branding/account.png","◎")}${S.user?.email===S.config?.adminEmail?nav("admin","Admin","admin.png","⚙"):""}</div><div class="navLabel">SUPPORT</div><div class="nav">${nav("help","Help & FAQ","support.png","?")}</div><div class="profile"><div class="profiletop"><img class="badge" src="/branding/account.png?v=4.1.0" onerror="this.src='/branding/account.svg?v=4.1.0'"><div><b>${esc(S.user?.displayName||S.user?.email)}</b><div class="muted small">${S.user?.role==="admin"?"Administrator":"Member"}</div></div></div><div class="profileActions"><button class="btn" onclick="S.tab='account';renderApp()">Account</button><button class="btn" onclick="logout()">Sign out</button></div></div></aside><main class="main"><div class="mobilebar"><button class="btn" onclick="openMenu()">☰ Menu</button><b>deploy-website</b><button class="btn primary" onclick="S.tab='deploy';renderApp()">+ Deploy</button></div><div id="view"></div></main></div></div><div id="modal" class="modal hidden"></div><div id="toast" class="toast hidden"></div>`;
 loadTab().then(()=>applyLanguage());
}

function openMenu(){$("#side")?.classList.add("open");$("#mobileOverlay")?.classList.add("open")}function closeMenu(){$("#side")?.classList.remove("open");$("#mobileOverlay")?.classList.remove("open")}
async function loadTab(){try{if(S.tab==="admin")return await adminView();if(S.tab==="account")return await accountView();if(S.tab==="help"){return $("#view").innerHTML=helpView()}const d=await api("/api/dashboard");S.projects=d.projects;$("#view").innerHTML=S.tab==="projects"?projectsView():S.tab==="deploy"?deployView():overviewView(d)}catch(e){toast(e.message||"Could not load data","error")}}
function overviewView(d){
 const recent=d.recent?.slice(0,8)||[];const projects=d.projects||[];
 return `<div class="pageShell"><div class="workspaceBanner"><div class="card workspaceMain"><div class="workspaceIdentity"><img src="/branding/logo.png?v=4.1.0" onerror="this.src='/branding/logo.svg?v=4.1.0'"><div><div class="kicker">WORKSPACE</div><b>deploy-website</b><span>Private deployment cloud · one place for every release.</span></div></div><div class="workspaceChips"><span class="workspaceChip"><strong>${d.stats.projects}</strong> projects</span><span class="workspaceChip"><strong>${d.stats.live}</strong> live</span><span class="workspaceChip"><strong>${d.stats.deployments}</strong> deployments</span><span class="workspaceChip">URL <strong>.${esc(S.config.domain)}</strong></span></div><div class="workspaceActions"><button class="btn" onclick="S.tab='projects';renderApp()">Manage projects</button><button class="btn" onclick="S.tab='help';renderApp()">Get help</button></div></div><div class="card releasePulse"><div class="pulseTop"><div><span class="kicker">RELEASE PULSE</span><b>LIVE</b></div><i></i></div><div class="pulseNumbers"><div><strong>${d.stats.deployments}</strong><span>releases</span></div><div><strong>${d.stats.live}</strong><span>live</span></div><div><strong>${d.stats.projects}</strong><span>projects</span></div></div><div class="pulseStatus"><i></i><div><b>Publishing ready</b><span>Snapshot-based workflow</span></div><em>→</em></div></div></div><div class="topbar"><div><div class="kicker">Workspace / Overview</div><h1 class="hero">Everything in one place.</h1><div class="sub">Your releases, projects, deployment history and system status in one focused workspace.</div></div><div class="actions"><button class="btn" onclick="refreshCurrent()">↻ Refresh</button><button class="btn primary" onclick="S.tab='deploy';renderApp()">+ New deployment</button></div></div><div class="stats">${stat("Projects",d.stats.projects,"total")}${stat("Live",d.stats.live,"live now")}${stat("Deployments",d.stats.deployments,"release records")}${stat("Storage",fmt(d.stats.storage),"used")}${S.user?.role==="admin"?stat("Members",d.stats.members||0,"registered accounts"):stat("Account","ACTIVE","signed in")}</div><div class="section quickGrid"><button class="card quickCard" onclick="S.tab='deploy';renderApp()"><div class="qicon">↑</div><b>Publish a new site</b><div class="muted small">ZIP, folder or index.html</div></button><button class="card quickCard" onclick="S.tab='projects';renderApp()"><div class="qicon">◈</div><b>Manage projects</b><div class="muted small">Releases, rollback and preview</div></button><button class="card quickCard" onclick="S.tab='account';renderApp()"><div class="qicon">◎</div><b>Edit account</b><div class="muted small">Profile and account settings</div></button>${S.user?.role==='admin'?`<button class="card quickCard" onclick="S.tab='admin';renderApp()"><div class="qicon">⚙</div><b>Admin</b><div class="muted small">Members, sites, settings and activity logs</div></button>`:`<button class="card quickCard" onclick="S.tab='help';renderApp()"><div class="qicon">?</div><b>Help & FAQ</b><div class="muted small">Frequently asked questions and quick answers</div></button>`}</div><div class="section"><div class="sectionhead"><div><div class="sectiontitle">Recent projects</div><div class="muted small">Your latest published sites</div></div><button class="btn" onclick="S.tab='projects';renderApp()">View all →</button></div><div class="grid">${projects.slice(0,6).map(p=>projectCard(p)).join('')||`<div class="card empty">No projects yet.<br><button class="btn primary" style="margin-top:13px" onclick="S.tab='deploy';renderApp()">Publish your first site</button></div>`}</div></div><div class="section two"><div class="card panel"><div class="sectionhead"><div><div class="sectiontitle">Recent activity</div><div class="muted small">Recent workspace activity</div></div></div><div class="list">${recent.map(a=>`<div class="listrow"><div><b>${esc(activityLabel(a.action))}</b><div class="muted small">${esc(a.actor||"system")}</div></div><div class="muted small">${date(a.at)}</div></div>`).join('')||`<div class="empty">No recent activity.</div>`}</div></div><div class="card panel releaseSnapshotPanel"><div class="sectionhead"><div><div class="sectiontitle">Release snapshot</div><div class="muted small">A compact view of what your workspace is ready to do next.</div></div><span class="pill">READY</span></div><div class="snapshotHero"><div class="snapshotGlyph">◈</div><div><b>Snapshot-first publishing</b><span>Each release keeps its own boundary, URL and recovery point.</span></div></div><div class="snapshotFacts"><div><span>RELEASE MODEL</span><b>Snapshot-based</b></div><div><span>LIVE URL</span><b>.${esc(S.config.domain)}</b></div><div><span>RECOVERY</span><b>Rollback ready</b></div></div><button class="snapshotAction" onclick="S.tab='deploy';renderApp()">Create the next release <span>→</span></button></div></div>${faqView(true)}${siteFooter()}</div>`;
}

function faqView(compact=false){return `<section class="section ${compact?'':'helpFaqSection'}"><div class="card helpHero"><div class="helpHeroTop"><div><div class="kicker">HELP CENTER</div><h2>Answers before you need them.</h2><p class="sub">Clear, practical answers for publishing, releases, accounts and everyday workspace questions.</p></div><div class="helpMark">?</div></div><div class="helpTopics"><span>Publishing</span><span>Releases</span><span>Accounts</span><span>Mobile</span></div></div><div class="helpGrid" style="margin-top:14px"><details class="card faq" open><summary><span>How do I publish a site?</span><b>+</b></summary><p>Open Deploy, choose a ZIP, folder or files, review the release target and publish. The result card shows the live URL without automatically moving you away.</p></details><details class="card faq"><summary><span>Why can an old version still appear?</span><b>+</b></summary><p>Give the browser a hard refresh first. Deploy Website sends controlled cache headers and versioned assets; external cache rules should not override them.</p></details><details class="card faq"><summary><span>What is Preview?</span><b>+</b></summary><p>Preview gives you a separate release destination for checking changes before you replace the live version.</p></details><details class="card faq"><summary><span>My verification email is missing. What should I do?</span><b>+</b></summary><p>Check Spam or Junk, then request another verification email from the account flow. Make sure the address you entered is correct.</p></details><details class="card faq"><summary><span>How does password reset work?</span><b>+</b></summary><p>Choose Forgot password on sign in. The reset link is single-use and expires, so request a fresh link if the old one is no longer valid.</p></details><details class="card faq"><summary><span>Does the dashboard work on mobile?</span><b>+</b></summary><p>Yes. Navigation, project cards, forms and deployment controls are designed to adapt to small screens without horizontal scrolling.</p></details><details class="card faq"><summary><span>Can I roll back a release?</span><b>+</b></summary><p>Open a project, view its release history and restore the snapshot you want. The previous release remains available as a recovery point.</p></details><details class="card faq"><summary><span>How do I change my language?</span><b>+</b></summary><p>Open Account and choose English or Türkçe under Interface language. Your choice is saved in this browser.</p></details></div></section>`}
function helpView(){return `<div class="pageShell helpPage"><div class="helpHeader"><div><div class="kicker">SUPPORT / HELP CENTER</div><h1 class="hero">Help & FAQ</h1><div class="sub">Clear answers for publishing, releases, accounts and common workspace issues.</div></div><div class="helpHeaderAction"><button class="btn primary" onclick="openReportModal()">Report an issue <span>→</span></button></div></div>${faqView(false)}<div class="section"><div class="card reportCard"><div class="reportIcon">?</div><div class="reportCopy"><div class="kicker">NEED A HAND?</div><h2>Something not working?</h2><p class="sub">Tell us what happened, what you expected and where it happened. A short report is enough.</p></div><button class="btn primary" onclick="openReportModal()">Report a problem <span>→</span></button></div></div>${siteFooter()}</div>`}
function openReportModal(){openModal(`<div class="modalbox reportModal"><div class="modalhead"><div><div class="kicker">SUPPORT</div><h2 style="margin:6px 0">Report an issue</h2><p class="muted small">Tell us what happened and where it happened.</p></div><button class="x" onclick="closeModal()">×</button></div><div class="formgrid"><div class="field"><label>CATEGORY</label><select id="reportCategory"><option>Bug</option><option>Deployment</option><option>Account</option><option>Email</option><option>UI / Mobile</option><option>Other</option></select></div><div class="field"><label>PAGE</label><input id="reportPage" value="${esc(location.pathname)}" readonly></div></div><div class="field"><label>SUBJECT</label><input id="reportSubject" maxlength="120" placeholder="Short description"></div><div class="field"><label>DETAILS</label><textarea id="reportMessage" maxlength="4000" rows="7" placeholder="What happened? What did you expect? Include steps to reproduce if possible."></textarea></div><div class="actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="submitIssueReport()">Send report</button></div><div id="reportStatus" class="muted small"></div></div>`) }
async function submitIssueReport(){const category=$("#reportCategory")?.value||"Other",subject=String($("#reportSubject")?.value||"").trim(),message=String($("#reportMessage")?.value||"").trim();if(!subject||!message){$("#reportStatus").textContent="Subject and details are required.";return}const btn=document.querySelector('.reportModal .btn.primary');if(btn)btn.disabled=true;try{await api('/api/feedback/report',{method:'POST',body:JSON.stringify({category,subject,message,page:location.pathname})});toast('Report sent — thank you');closeModal()}catch(e){$("#reportStatus").textContent=e.message||'Could not send report.';if(btn)btn.disabled=false}}
function activityLabel(a){return ({login:"Signed in",deployment_published:"Deployment published",deployment_rollback:"Deployment rolled back",project_updated:"Project updated",project_deleted:"Project deleted",member_registered:"New member registered",member_banned:"Member restricted",member_unbanned:"Member restriction removed",admin_project_deleted:"Admin project sildi",project_status_changed:"Site status changed",profile_updated:"Profile updated",password_changed:"Password changed",preview_published:"Preview published"}[a]||a)}
async function accountView(){try{const d=await api("/api/auth/me");S.profile=d.user;const u=d.user;const initials=esc((u.firstName?.[0]||u.email?.[0]||"K").toUpperCase());const lang=getLang();$("#view").innerHTML=`<div class="topbar"><div><div class="kicker">ACCOUNT / PROFILE</div><h1 class="hero">Account</h1><div class="sub">Manage your profile, password, language and support preferences.</div></div><div class="actions"><button class="btn" onclick="logout()">Sign out</button></div></div><div class="accountHero card"><div class="accountHeroAvatar"><img src="/branding/account.png?v=4.1.0" onerror="this.style.display='none';this.parentElement.textContent='${initials}'"></div><div class="accountHeroCopy"><div class="kicker">YOUR ACCOUNT</div><h2>${esc(u.displayName||u.email)}</h2><p>${esc(u.email)}</p><div class="accountBadges"><span class="pill">${u.emailVerified?'VERIFIED':'UNVERIFIED'}</span><span class="pill">${esc(u.role||'member').toUpperCase()}</span><span class="pill">${u.banned?'RESTRICTED':'ACTIVE'}</span></div></div><div class="accountHeroMeta"><span>Member since</span><b>${date(u.createdAt)}</b><span>Last login</span><b>${date(u.lastLoginAt)}</b></div></div><div class="two accountGrid"><div class="card panel"><div class="sectionhead"><div><div class="sectiontitle">Profile</div><div class="muted small">The information shown across your workspace.</div></div><div class="adminAvatar accountInlineAvatar"><img src="/branding/account.png?v=4.1.0" onerror="this.style.display='none';this.parentElement.textContent='${initials}'"></div></div><div class="formgrid"><div class="field"><label>FIRST NAME</label><input id="afirst" value="${esc(u.firstName)}"></div><div class="field"><label>LAST NAME</label><input id="alast" value="${esc(u.lastName)}"></div></div><div class="formgrid"><div class="field"><label>USERNAME</label><input id="auser" value="${esc(u.username)}"></div><div class="field"><label>PHONE</label><input id="aphone" value="${esc(u.phone)}"></div></div><div class="field"><label>WEBSITE</label><input id="aweb" value="${esc(u.website)}" placeholder="https://example.com"></div><div class="field"><label>BIO</label><textarea id="abio" placeholder="A short introduction">${esc(u.bio)}</textarea></div><div class="actions"><button class="btn primary" onclick="saveProfile()">Save profile</button></div></div><div class="card panel"><div class="sectionhead"><div><div class="sectiontitle">Security</div><div class="muted small">Change your password without leaving the workspace.</div></div><span class="pill">PRIVATE</span></div><div class="field"><label>CURRENT PASSWORD</label><input id="acurrent" type="password"></div><div class="field"><label>NEW PASSWORD</label><input id="anew" type="password" placeholder="At least 10 characters"></div><div class="field"><label>CONFIRM NEW PASSWORD</label><input id="anew2" type="password"></div><button class="btn" onclick="changePassword()">Update password</button><div class="section"><div class="sectiontitle">Email status</div><div class="statusCard"><span class="dot"><i></i>${u.emailVerified?'Email verified':'Verification required'}</span><span class="muted small">${u.emailVerified?'Your account email is verified.':'Use the verification email from deploy-website.'}</span></div></div></div><div class="card panel"><div class="sectionhead"><div><div class="sectiontitle">Interface language</div><div class="muted small">Choose how deploy-website is displayed on this browser.</div></div><span class="pill">${lang==='en'?'EN':'TR'}</span></div><div class="languagePicker"><button class="langChoice ${lang==='en'?'active':''}" onclick="setLanguage('en')"><b>English</b><span>Default</span></button><button class="langChoice ${lang==='tr'?'active':''}" onclick="setLanguage('tr')"><b>Türkçe</b><span>Türkçe arayüz</span></button></div><div class="notice">Your language preference is stored locally on this browser and does not affect your projects.</div></div><div class="card panel accountHelpCard"><div class="sectionhead"><div><div class="sectiontitle">Need help?</div><div class="muted small">Report a bug, deployment problem or account issue directly.</div></div></div><div class="accountHelpActions"><button class="btn primary" onclick="openReportModal()">Report an issue</button><button class="btn" onclick="S.tab='help';renderApp()">Open Help Center</button></div></div></div>${siteFooter()}</div>`;applyLanguage()}catch(e){toast(e.message||"Account could not be loaded","error")}}


async function saveProfile(){try{const d=await api("/api/account/profile",{method:"PATCH",body:JSON.stringify({firstName:$("#afirst").value,lastName:$("#alast").value,username:$("#auser").value,phone:$("#aphone").value,website:$("#aweb").value,bio:$("#abio").value})});S.user=d.user;toast("Profile saved");loadTab()}catch(e){toast(e.message,"error")}}
async function changePassword(){const a=$("#acurrent").value,b=$("#anew").value,c=$("#anew2").value;if(b!==c)return toast("New passwords do not match","error");try{await api("/api/account/password",{method:"POST",body:JSON.stringify({currentPassword:a,newPassword:b})});toast("Password changed");$("#acurrent").value=$("#anew").value=$("#anew2").value=""}catch(e){toast(e.message,"error")}}

