function setLanguage(lang){localStorage.setItem('kc_lang_v4',lang==='tr'?'tr':'en');S.language=getLang();renderApp()}
function applyLanguage(){if(getLang()==='en')return;const root=document.body;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){const raw=n.nodeValue.trim();if(raw&&EN_TR[raw])n.nodeValue=n.nodeValue.replace(raw,EN_TR[raw])}root.querySelectorAll('[placeholder],[title],[aria-label]').forEach(el=>{for(const attr of ['placeholder','title','aria-label']){const v=el.getAttribute(attr);if(v&&EN_TR[v])el.setAttribute(attr,EN_TR[v])}})}
function projectsView(){const list=S.projects.filter(p=>(p.name+" "+p.slug).toLowerCase().includes(S.query.toLowerCase()));return `<div class="pageShell"><div class="topbar"><div><div class="kicker">Workspace</div><h1 class="hero">Projects</h1><div class="sub">All sites, URLs and release statuses.</div></div><div class="actions"><div class="search"><input placeholder="Search projects…" value="${esc(S.query)}" oninput="S.query=this.value;loadTab()"></div><button class="btn primary" onclick="S.tab='deploy';renderApp()">+ Deploy</button></div></div><div class="grid">${list.map(p=>projectCard(p)).join("")||`<div class="card empty">No matching project found.</div>`}</div>${faqView(true)}${siteFooter()}</div>`}
function deployView(){return `<div class="pageShell"><div class="topbar"><div><div class="kicker">Publish center</div><h1 class="hero">New deployment.</h1><div class="sub">Choose your files, review the release flow and get the live link from the result. There is no automatic redirect after selection.</div></div></div><div class="card panel"><div class="formgrid"><div class="field"><label>TARGET PROJECT</label><select id="targetProject"><option value="">+ Create new project</option>${S.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} — ${esc(p.slug)}</option>`).join("")}</select></div><div class="field"><label>PROJECT NAME / TITLE</label><input id="pname" placeholder="My Portfolio"></div></div><div class="formgrid"><div class="field"><label>SUBDOMAIN <span class="optional">(for a new project)</span></label><input id="slug" placeholder="portfolio"></div><div class="field"><label>RELEASE TYPE</label><select id="deployMode"><option value="live">Publish live</option><option value="preview">Create preview only</option></select></div></div><div class="drop" id="drop" onclick="openFilePicker()" ondragover="event.preventDefault();this.classList.add('drag')" ondragleave="this.classList.remove('drag')" ondrop="dropFiles(event)"><div><div class="dropicon">☁</div><h3 style="margin:12px 0 5px">Drop your files here</h3><div class="muted small">ZIP, folder, index.html or multiple files</div></div></div><div class="uploadChoices"><button class="choice" onclick="openFilePicker()"><b>📄 Files</b><span>Select index.html, CSS, JS and images together.</span></button><button class="choice" onclick="openFolderPicker()"><b>📁 Folder</b><span>Select a full project folder and preserve paths.</span></button><button class="choice" onclick="openZipPicker()"><b>📦 ZIP</b><span>The easiest way to publish as one package.</span></button></div><input id="filePicker" type="file" multiple accept=".zip,application/zip,.html,text/html,.css,text/css,.js,application/javascript,image/*" style="display:none" onchange="chooseFiles(this.files)"><input id="folderPicker" type="file" multiple webkitdirectory directory style="display:none" onchange="chooseFiles(this.files)"><input id="zipInput" type="file" accept=".zip,application/zip" style="display:none" onchange="chooseFiles(this.files)"><div id="selected" class="uploadSummary hidden"></div><div class="publishActions"><div id="progress" class="deployStatus"><span>Your release summary will appear here after you choose files.</span></div><button id="publishBtn" class="btn primary" disabled onclick="publishSelected()">Continue to publish →</button></div><div id="publishResult"></div></div><div class="section grid"><div class="card panel"><b>Automatic discovery</b><p class="muted small">Root index.html plus dist, build, out and public are supported.</p></div><div class="card panel"><b>Preview URL</b><p class="muted small">Create a separate preview link before publishing live.</p></div><div class="card panel"><b>After publishing</b><p class="muted small">The result screen gives you the link without sending you to another page automatically.</p></div></div>${faqView(true)}${siteFooter()}</div>`}
function openFilePicker(){$("#filePicker")?.click()}function openFolderPicker(){$("#folderPicker")?.click()}function openZipPicker(){$("#zipInput")?.click()}
function dropFiles(e){e.preventDefault();$("#drop")?.classList.remove("drag");chooseFiles(e.dataTransfer.files)}
function chooseFiles(files){S.selectedFiles=Array.from(files||[]);const box=$("#selected"),btn=$("#publishBtn"),progress=$("#progress");if(!box||!btn||!progress)return;if(!S.selectedFiles.length){box.classList.add("hidden");btn.disabled=true;progress.innerHTML="<span>Your release summary will appear here after you choose files.</span>";return}const names=S.selectedFiles.slice(0,8).map(f=>f.webkitRelativePath||f.name);const total=S.selectedFiles.reduce((n,f)=>n+(f.size||0),0);box.classList.remove("hidden");box.innerHTML=`<div class="card uploadSummaryCard"><b>${S.selectedFiles.length} files ready</b><div class="muted small" style="margin-top:5px">Total ${fmt(total)} · Publishing has not started. Review the files and continue.</div><div class="fileList">${names.map(n=>`<span class="fileTag">${esc(n)}</span>`).join("")}${S.selectedFiles.length>8?`<span class="fileTag">+ ${S.selectedFiles.length-8} file daha</span>`:""}</div></div><div class="card uploadSummaryCard"><b>Release target</b><div class="muted small" style="margin-top:5px">${esc($("#pname")?.value?.trim()||"Yeni project")} · ${esc($("#slug")?.value?.trim()||"automatic subdomain")}</div><div class="muted small" style="margin-top:8px">${$("#deployMode")?.value==="preview"?"A preview will be created":"A live release will be published"}</div></div>`;btn.disabled=false;progress.innerHTML=`<span>✓ Files ready · continue to publish.</span>`}
function setPublishProgress(label,step=1,done=false){const p=$("#progress"),r=$("#publishResult");if(p)p.innerHTML=`${done?'<span class="spinner done">✓</span>':'<span class="spinner"></span>'}<span>${esc(label)}</span>`;if(r&&!done)r.innerHTML=`<div class="publishSteps"><div class="publishStep ${step>=1?'active':''}"><b>1</b>Preparing</div><div class="publishStep ${step>=2?'active':''}"><b>2</b>Uploading</div><div class="publishStep ${step>=3?'active':''}"><b>3</b>Publishing</div><div class="publishStep ${step>=4?'active':''}"><b>4</b>LIVE</div></div>`}
async function publishSelected(){const files=S.selectedFiles||[];if(!files.length)return;const btn=$("#publishBtn");btn.disabled=true;setPublishProgress("Preparing files…",1);try{await new Promise(r=>setTimeout(r,180));setPublishProgress("Uploading files to the server…",2);const zip=files.length===1 && /\.zip$/i.test(files[0].name);let d;if(zip){const fd=new FormData();fd.append("file",files[0]);fd.append("name",$("#pname")?.value?.trim()||files[0].name.replace(/\.zip$/i,""));fd.append("slug",$("#slug")?.value?.trim()||"");fd.append("projectId",$("#targetProject")?.value||"");fd.append("preview",$("#deployMode")?.value==="preview"?"true":"false");d=await fetch("/api/deploy/zip",{method:"POST",body:fd}).then(async r=>{const x=await r.json();if(!r.ok)throw new Error(x.error||"Deployment failed");return x})}else{const fd=new FormData();fd.append("name",$("#pname")?.value?.trim()||((files[0].name||"site").replace(/\.[^.]+$/,"")));fd.append("slug",$("#slug")?.value?.trim()||"");fd.append("projectId",$("#targetProject")?.value||"");fd.append("preview",$("#deployMode")?.value==="preview"?"true":"false");files.forEach(f=>{fd.append("files",f);fd.append("paths",f.webkitRelativePath||f.name)});d=await fetch("/api/deploy/folder",{method:"POST",body:fd}).then(async r=>{const x=await r.json();if(!r.ok)throw new Error(x.error||"Deployment failed");return x})}setPublishProgress("Preparing release…",3);await new Promise(r=>setTimeout(r,300));const preview=$("#deployMode")?.value==="preview";const url=preview?d.project.previewUrl:d.project.url;setPublishProgress("LIVE — bağlantın hazır.",4,true);$("#publishResult").innerHTML=`<div class="publishResult"><div class="publishResultTop"><div><div class="kicker">${preview?'PREVIEW HAZIR':'YAYINDA'}</div><div class="publishResultUrl">${esc(url)}</div><div class="muted small" style="margin-top:5px">${preview?'You can test this release.':'This release is live.'} Files processed: ${d.project.files||files.length} files processed.</div></div><span class="pill">${preview?"PREVIEW":"LIVE"}</span></div><div class="publishResultActions"><button class="btn primary" onclick="window.open('${esc(url)}','_blank')">Open site ↗</button><button class="btn" onclick="navigator.clipboard?.writeText('${esc(url)}');toast('Link copied')">Copy link</button><button class="btn" onclick="S.tab='projects';renderApp()">Back to projects</button><button class="btn" onclick="S.selectedFiles=[];S.tab='deploy';renderApp()">New deployment</button></div></div>`;toast(preview?"Preview ready 🎉":"Site is live 🎉");S.projects=(await api("/api/dashboard")).projects}catch(e){setPublishProgress("Publishing failed.",1,true);$("#publishResult").innerHTML=`<div class="authError" style="margin-top:12px">${esc(e.message||"Deployment failed")}</div>`;toast(e.message||"Deployment failed","error")}finally{btn.disabled=false}}

function quickRedeploy(id){S.tab="deploy";renderApp();setTimeout(()=>{const t=$("#targetProject");if(t)t.value=id;},0)}

async function projectDetails(id){try{const d=await api(`/api/projects/${id}`);openModal(`<div class="modalbox"><div class="modalhead"><div><div class="kicker">Project details</div><h2 style="margin:6px 0">${esc(d.project.name)}</h2><div class="url">${esc(d.project.url)}</div></div><button class="x" onclick="closeModal()">×</button></div><div class="stats" style="grid-template-columns:repeat(3,1fr);margin-top:18px">${stat("Dosya",d.project.files||0)}${stat("Boyut",fmt(d.project.bytes))}${stat("Views",d.project.views||0)}</div><div class="actions" style="margin-top:16px"><button class="btn primary" onclick="quickRedeploy('${id}');closeModal()">+ Upload new release</button></div><div class="section"><div class="sectiontitle">Deployment history</div><div class="list" style="margin-top:10px">${d.deployments.map(x=>`<div class="listrow"><div><b>${esc(x.message||"Deployment")}</b><div class="muted small">${date(x.createdAt)} • ${x.files||0} file • ${fmt(x.bytes)}</div></div><div class="actions">${x.previewHost?`<button class="btn" onclick="window.open('https://${esc(x.previewHost)}.${esc(S.config.domain)}','_blank')">Preview ↗</button>`:""}<button class="btn ${x.id===d.project.currentDeploymentId?"success":""}" onclick="rollback('${id}','${x.id}')">${x.id===d.project.currentDeploymentId?"Aktif":"Geri al"}</button></div></div>`).join("")||`<div class="empty">Deployment history yok.</div>`}</div></div></div>`)}catch(e){toast(e.message,"error")}}
async function rollback(pid,did){if(!confirm("Restore this deployment release?"))return;try{await api(`/api/projects/${pid}/rollback/${did}`,{method:"POST"});toast("Release rolled back");closeModal();loadTab()}catch(e){toast(e.message,"error")}}
async function editProject(id){const p=S.projects.find(x=>x.id===id);if(!p)return;openModal(`<div class="modalbox"><div class="modalhead"><div><div class="kicker">Project settings</div><h2>${esc(p.name)}</h2></div><button class="x" onclick="closeModal()">×</button></div><div class="field"><label>PROJE ADI</label><input id="ename" value="${esc(p.name)}"></div><div class="field"><label>URL</label><input value="${esc(p.url)}" readonly></div><div class="actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveProject('${id}')">Save</button><button class="btn danger" onclick="deleteProject('${id}')">Projectyi sil</button></div></div>`)}
async function saveProject(id){try{await api(`/api/projects/${id}`,{method:"PATCH",body:JSON.stringify({name:$("#ename").value})});toast("Project updated");closeModal();loadTab()}catch(e){toast(e.message,"error")}}
async function deleteProject(id){if(!confirm("Permanently delete this project and all deployment snapshots?"))return;try{await api(`/api/projects/${id}`,{method:"DELETE"});toast("Project deleted");closeModal();loadTab()}catch(e){toast(e.message,"error")}}
function refreshCurrent(){loadTab()}

async function adminView(){try{
  const d=await api("/api/admin/overview");S.admin=d;let sys={};try{sys=await api("/api/admin/system")}catch{} const m=d.metrics; const activity=d.activity||[];
  $("#view").innerHTML=`<div class="topbar"><div><div class="kicker">Workspace / Admin</div><h1 class="hero">Admin</h1><div class="sub">deploy-website members, projects, system settings and activity records.</div></div><div class="actions"><button class="btn" onclick="adminRefresh()">↻ Refresh</button><button class="btn primary" onclick="S.tab='deploy';renderApp()">+ New deployment</button></div></div><div class="adminHero"><div class="card adminBanner"><div class="kicker">CONTROL CENTER</div><h2>Admin control center</h2><p class="sub">Moderation, releases and system controls in one focused view. Important actions stay visible.</p><div class="actions" style="justify-content:flex-start;margin-top:14px"><button class="btn primary" onclick="document.getElementById('membersSection').scrollIntoView({behavior:'smooth'})">Manage members</button><button class="btn" onclick="document.getElementById('activitySection').scrollIntoView({behavior:'smooth'})">Activity log</button></div></div><div class="card adminPulse"><div class="sectiontitle">System overview</div><div class="pulseLine"><span><i class="onlineDot"></i>API</span><b>ONLINE</b></div><div class="pulseLine"><span>Server</span><b>${esc(sys.node||"Node")}</b></div><div class="pulseLine"><span>Uptime</span><b>${sys.uptime?Math.floor(sys.uptime/3600)+" hours":"—"}</b></div><div class="pulseLine"><span>Storage</span><b>${fmt(sys.storage||m.storage)}</b></div></div></div><div class="section stats">${stat("Members",m.users,"total accounts")}${stat("Sites",m.projects,"total projects")}${stat("Live",m.live,"live")}${stat("Restricted",m.banned,"restricted")}${stat("Storage",fmt(m.storage),"total")}</div><div class="section adminGrid"><section class="adminSection card panel" id="membersSection"><div class="adminSectionTitle"><div><h3>Members</h3><p>Manage accounts, roles and moderation status.</p></div><span class="pill">${m.users} ACCOUNTS</span></div><div class="tablewrap"><table class="table"><tr><th>User</th><th>Role</th><th>Status</th><th>Joined</th><th>Restriction reason</th><th>Actions</th></tr>${d.users.map(u=>`<tr><td><div class="adminUser"><div class="adminAvatar"><img src="/branding/account.png?v=4.1.0" onerror="this.style.display='none';this.parentElement.textContent='${esc((u.displayName||u.email||'K').slice(0,1).toUpperCase())}'"></div><div><b>${esc(u.displayName||u.email)}</b><div class="muted">${esc(u.email)}</div></div></div></td><td>${esc(u.role)}</td><td>${u.banned?'<span class="pill red">RESTRICTED</span>':'<span class="pill">ACTIVE</span>'}</td><td>${date(u.createdAt)}</td><td>${esc(u.banReason||"—")}</td><td><div class="activityAction">${u.email===S.config.adminEmail?'<b>ADMIN</b>':`<button class="btn" onclick="banUser('${u.id}',${!u.banned})">${u.banned?"Unrestrict":"Ban"}</button><button class="btn danger" onclick="removeUser('${u.id}')">Delete</button>`}</div></td></tr>`).join("")}</table></div></section><section class="adminSection card panel"><div class="adminSectionTitle"><div><h3>System settings</h3><p>Manage core workspace behavior.</p></div><span class="pill">SETTINGS</span></div><div class="settingGrid"><div class="settingCard wide"><div class="settingLabel">BRAND</div><div class="field" style="margin:7px 0 0"><input id="brand" value="${esc(d.settings.brandName)}" maxlength="40"></div></div><div class="settingCard"><div class="settingLabel">MAX PROJECTS / USER</div><div class="field" style="margin:7px 0 0"><input id="limit" type="number" min="1" max="100" value="${d.settings.maxProjectsPerUser}"></div></div><div class="settingCard"><div class="toggleRow"><div><div class="settingLabel">REGISTRATION</div><div class="settingValue">${d.settings.registration?'Enabled':'Disabled'}</div></div><button class="switch ${d.settings.registration?'on':''}" onclick="toggleSetting('registration',${!d.settings.registration})" aria-label="Registration"></button></div></div><div class="settingCard"><div class="toggleRow"><div><div class="settingLabel">MAINTENANCE</div><div class="settingValue">${d.settings.maintenance?'Enabled':'Disabled'}</div></div><button class="switch ${d.settings.maintenance?'on':''}" onclick="toggleSetting('maintenance',${!d.settings.maintenance})" aria-label="Maintenance"></button></div></div></div><div class="actions" style="justify-content:flex-start;margin-top:11px"><button class="btn primary" onclick="saveSettings()">Save settings</button></div><div class="adminNote" style="margin-top:11px">Brand and limits apply immediately. When maintenance is enabled, regular members cannot publish new releases.</div></section><section class="adminSection full card panel"><div class="adminSectionTitle"><div><h3>Site management</h3><p>Suspend, republish, open or permanently delete projects from one list.</p></div><span class="pill">${d.projects.length} SITES</span></div><div class="tablewrap"><table class="table"><tr><th>Site</th><th>Owner</th><th>Status</th><th>Views</th><th>Actions</th></tr>${d.projects.map(p=>`<tr><td><b>${esc(p.name)}</b><div class="muted">${esc(p.slug)}.${esc(S.config.domain)}</div></td><td>${esc(p.ownerEmail||"—")}</td><td>${statusPill(p.status)}</td><td>${p.views||0}</td><td><div class="activityAction"><button class="btn" onclick="setProjectStatus('${p.id}','${p.status==='live'?'suspended':'live'}')">${p.status==='live'?'Suspend':'Publish'}</button><button class="btn" onclick="window.open('${esc(p.url)}','_blank')">Open ↗</button><button class="btn danger" onclick="adminDeleteProject('${p.id}')">Delete</button></div></td></tr>`).join("")||`<tr><td colspan="5" class="muted">No sites.</td></tr>`}</table></div></section><section class="adminSection full card panel" id="activitySection"><div class="adminSectionTitle"><div><h3>Activity log</h3><p>Who did what? Delete records individually or clear the entire log.</p></div><div class="actions"><button class="btn danger" onclick="clearActivity()">Clear all</button></div></div><div class="activityToolbar"><div class="search"><input id="activitySearch" placeholder="Search activity…" oninput="filterActivity()"></div><span class="muted small">${activity.length} records</span></div><div class="tablewrap"><table class="table"><thead><tr><th>Time</th><th>Event</th><th>Actor</th><th>Details</th><th></th></tr></thead><tbody id="activityRows">${activityRows(activity)}</tbody></table></div></section><section class="adminSection full card panel" id="reportsSection"><div class="adminSectionTitle"><div><h3>Issue reports</h3><p>Recent reports from members. Use the report ID when following up.</p></div><span class="pill">${(d.feedbackReports||[]).length} REPORTS</span></div><div class="tablewrap"><table class="table"><thead><tr><th>Time</th><th>Category</th><th>Subject</th><th>User</th><th>Page</th><th>Status</th></tr></thead><tbody>${(d.feedbackReports||[]).slice(0,50).map(r=>`<tr><td>${date(r.createdAt)}</td><td><span class="pill">${esc(r.category)}</span></td><td><b>${esc(r.subject)}</b><div class="muted activityMeta">${esc(r.message).slice(0,180)}</div></td><td>${esc(r.email)}</td><td>${esc(r.page)}</td><td>${esc(r.status||"new").toUpperCase()}</td></tr>`).join("")||`<tr><td colspan="6" class="empty">No issue reports.</td></tr>`}</tbody></table></div></section></div>${siteFooter()}`;
}catch(e){toast(e.message||"Could not load admin data","error")}}
function activityRows(list){return (list||[]).slice(0,200).map(a=>`<tr><td>${date(a.at)}</td><td><b>${esc(activityLabel(a.action))}</b></td><td>${esc(a.actor||"system")}</td><td class="activityMeta" title="${esc(JSON.stringify(a.meta||{}))}">${esc(JSON.stringify(a.meta||{}))}</td><td><button class="btn danger" onclick="deleteActivity('${a.id}')">Delete</button></td></tr>`).join("")||`<tr><td colspan="5" class="empty">No records found.</td></tr>`}
function filterActivity(){const q=String($("#activitySearch")?.value||"").toLowerCase();const list=(S.admin?.activity||[]).filter(a=>(activityLabel(a.action)+" "+(a.actor||"")+" "+JSON.stringify(a.meta||{})).toLowerCase().includes(q));const el=$("#activityRows");if(el)el.innerHTML=activityRows(list)}
async function deleteActivity(id){if(!confirm("Delete this activity record?"))return;try{await api(`/api/admin/activity/${id}`,{method:"DELETE"});S.admin.activity=(S.admin.activity||[]).filter(a=>a.id!==id);filterActivity();toast("Activity record deleted")}catch(e){toast(e.message,"error")}}
async function clearActivity(){if(!confirm("Permanently clear all activity records?"))return;try{await api("/api/admin/activity",{method:"DELETE"});S.admin.activity=[];filterActivity();toast("Activity log cleared")}catch(e){toast(e.message,"error")}}


async function adminRefresh(){adminView()}
async function banUser(id,banned){let reason="";if(banned){reason=prompt("Restriction reason (optional):")||"Restricted by administrator."}try{await api(`/api/admin/users/${id}`,{method:"PATCH",body:JSON.stringify({banned,reason})});toast(banned?"User restricted":"Restriction removed");adminRefresh()}catch(e){toast(e.message,"error")}}
async function removeUser(id){if(!confirm("Permanently delete this user account?"))return;try{await api(`/api/admin/users/${id}`,{method:"DELETE"});toast("User deleted");adminRefresh()}catch(e){toast(e.message,"error")}}
async function setProjectStatus(id,status){try{await api(`/api/admin/projects/${id}/status`,{method:"PATCH",body:JSON.stringify({status})});toast(status==='live'?"Site is live again":"Site suspended");adminRefresh()}catch(e){toast(e.message,"error")}}
async function adminDeleteProject(id){if(!confirm("Permanently delete this site, its deployment history and snapshots?"))return;try{await api(`/api/admin/projects/${id}`,{method:"DELETE"});toast("Site deleted by admin");adminRefresh()}catch(e){toast(e.message,"error")}}
async function toggleSetting(key,value){try{await api("/api/admin/settings",{method:"PATCH",body:JSON.stringify({[key]:value})});toast("Setting updated");adminRefresh()}catch(e){toast(e.message,"error")}}
async function saveSettings(){try{await api("/api/admin/settings",{method:"PATCH",body:JSON.stringify({brandName:$("#brand").value,maxProjectsPerUser:Number($("#limit").value)})});toast("Settings kaydedildi");adminRefresh()}catch(e){toast(e.message,"error")}}
async function logout(){try{await api("/api/auth/logout",{method:"POST"})}catch{}S.user=null;renderAuth("login")}
boot();
